#include <vector>
#include <algorithm>

using namespace std;

class Solution {
public:
    int maxProfit(int n, vector<vector<int>>& edges, vector<int>& score) {
        vector<int> need(n, 0);
        for (const auto& e : edges) {
            need[e[1]] |= (1 << e[0]);
        }
        int maxMask = 1 << n;
        vector<int> dp(maxMask, -1);
        dp[0] = 0;

        for (int mask = 0; mask < maxMask; ++mask) {
            if (dp[mask] == -1) continue;
            int pos = __builtin_popcount(mask) + 1;
            for (int i = 0; i < n; ++i) {
                if (!(mask & (1 << i))) {
                    if ((mask & need[i]) == need[i]) {
                        int newMask = mask | (1 << i);
                        dp[newMask] = max(dp[newMask], dp[mask] + score[i] * pos);
                    }
                }
            }
        }
        return dp[maxMask - 1];
    }
};

import java.util.*;

class Solution {
    public int maxProfit(int n, int[][] edges, int[] score) {
        int[] need = new int[n];
        for (int[] e : edges) {
            need[e[1]] |= (1 << e[0]);
        }
        int maxMask = 1 << n;
        int[] dp = new int[maxMask];
        Arrays.fill(dp, -1);
        dp[0] = 0;

        for (int mask = 0; mask < maxMask; mask++) {
            if (dp[mask] == -1) continue;
            int pos = Integer.bitCount(mask) + 1;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) == 0) {
                    if ((mask & need[i]) == need[i]) {
                        int newMask = mask | (1 << i);
                        dp[newMask] = Math.max(dp[newMask], dp[mask] + score[i] * pos);
                    }
                }
            }
        }
        return dp[maxMask - 1];
    }
}

var maxProfit = function(n, edges, score) {
    const need = new Array(n).fill(0);
    for (const [u, v] of edges) {
        need[v] |= (1 << u);
    }
    const maxMask = 1 << n;
    const dp = new Array(maxMask).fill(-1);
    dp[0] = 0;

    const popcount = x => {
        let c = 0;
        while (x > 0) { c += (x & 1); x >>= 1; }
        return c;
    };

    for (let mask = 0; mask < maxMask; mask++) {
        if (dp[mask] === -1) continue;
        const pos = popcount(mask) + 1;
        for (let i = 0; i < n; i++) {
            if (!(mask & (1 << i))) {
                if ((mask & need[i]) === need[i]) {
                    const newMask = mask | (1 << i);
                    const val = dp[mask] + score[i] * pos;
                    if (val > dp[newMask]) dp[newMask] = val;
                }
            }
        }
    }
    return dp[maxMask - 1];
};
